def split_fields(text: str) -> list[str]:
    fields = []
    current = ""
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch == "\\":
            if i + 1 >= n:
                raise ValueError("dangling backslash")
            nxt = text[i + 1]
            if nxt == "," or nxt == "\\":
                current += nxt
                i += 2
            else:
                raise ValueError("invalid escape")
        elif ch == ",":
            fields.append(current)
            current = ""
            i += 1
        else:
            current += ch
            i += 1
    fields.append(current)
    return fields

